import torch.nn as nn
class M(nn.Module):
    def __init__(self):
        super().__init__()
        self.fc = nn.Linear(4, 2)
    def forward(self, x):
        return self.fc(x)
model = M(); print(sum(p.numel() for p in model.parameters()))

import torch; import torch.nn as nn
class M(nn.Module):
    def __init__(self):
        super().__init__()
        self.w = nn.Parameter(torch.randn(3, 4))
model = M(); print(f'param_count: {len(list(model.parameters()))}')

import torch.nn as nn; model = nn.Linear(4, 2)
for p in model.parameters():
    p.requires_grad_(False)
print(sum(1 for p in model.parameters() if p.requires_grad))
